WITH lines AS (SELECT id, created_at, coupon_codes, key, attr_value FROM carts LATERAL VIEW OUTER EXPLODE(attributes) e AS key, attr_value), lines_carts AS (SELECT attr_value, code FROM lines LATERAL VIEW EXPLODE(coupon_codes) e AS code), valid AS (SELECT *, CASE WHEN code = 'VIP' THEN 1 ELSE 0 END AS is_vip, COALESCE(code, 'N/A') AS code_clean FROM lines_carts WHERE code IS NOT NULL), enriched AS (SELECT attr_value, code, MAX(is_vip) OVER w_part AS code_max_is_vip, PERCENT_RANK() OVER w_running AS is_vip_percent_rank, CUME_DIST() OVER (ORDER BY is_vip) AS is_vip_cume_dist, COUNT(is_vip) OVER w_part AS code_count_is_vip, STDDEV_SAMP(is_vip) OVER w_part AS code_stddev_samp_is_vip FROM valid WINDOW w_part AS (PARTITION BY code), w_running AS (PARTITION BY code ORDER BY is_vip DESC NULLS FIRST)), metrics AS (SELECT *, ROUND(code_count_is_vip / SUM(code_count_is_vip) OVER (PARTITION BY code), 4) AS code_count_is_vip_share, AVG(code_stddev_samp_is_vip) OVER (PARTITION BY code) AS code_avg_code_stddev_samp_is_vip, PERCENT_RANK() OVER (PARTITION BY code ORDER BY is_vip_cume_dist) AS is_vip_cume_dist_percent_rank FROM enriched), metrics_carts AS (SELECT code, code_max_is_vip, is_vip_percent_rank, code_stddev_samp_is_vip, code_count_is_vip_share, is_vip_cume_dist_percent_rank, ROUND(code_count_is_vip / SUM(code_count_is_vip) OVER (PARTITION BY code), 4) AS code_count_is_vip_share_2 FROM metrics), enriched_carts AS (SELECT *, STDDEV_SAMP(code_count_is_vip_share_2) OVER (PARTITION BY code) AS code_stddev_samp_code_count_is_vip_share_2 FROM metrics_carts WHERE code_count_is_vip_share_2 < 0.2) SELECT code, code_max_is_vip, code_count_is_vip_share, code_count_is_vip_share_2, code_stddev_samp_code_count_is_vip_share_2 FROM enriched_carts ORDER BY code_count_is_vip_share, code_stddev_samp_code_count_is_vip_share_2 DESC;
